s=s.replace("D/'native_analysis_pool_v2.py'",'self.pool_module');s=s.replace('def evaluate(self,route,output,*,physical_reference=None,reuse=True):','def evaluate(self,route,output,*,physical_reference=None,reuse=True,native_observation=None):');s=s.replace("native=self.pool.analyze(route,echo=True,reuse=reuse);rd=b/'runs/state';rd.mkdir(parents=True)","native=self.pool.analyze(route,echo=True,reuse=reuse) if native_observation is None else native_observation;assert native['static_identity']==self.pool.identity and native['route_sha256']==sha(route);assert all(sha(p)==h for p,h in native['artifact_sha256'].items());rd=b/'runs/state';rd.mkdir(parents=True)")
