s=s.replace("native_analysis_calls=0 if native['reused'] else 1,route_search_calls=0", "native_analysis_calls=0 if native['reused'] or native_observation is not None else 1,consumed_already_executed_worker_receipt=native_observation is not None,native_transaction_calls=0 if native_observation is not None or not repair else 1,native_worker_query_count=query_count,route_search_calls=0 if native_observation is not None else query_count")
